   684→void tmp94c241_device::admod1_w(uint8_t data)
   685→{
   686→	// Preserve read-only bits
   687→	data = (m_ad_mode1 & 0xc0) | ( data & 0x34 );
   688→
   689→	// Check for A/D conversion start
   690→	if (data & 0x04)
   691→	{
   692→		data &= ~0x04;
   693→		data |= 0x40;
   694→
   695→		switch ((m_ad_mode2 >> 4) & 3)
   696→		{
   697→			case 0: m_ad_cycles_left = 160; break;
   698→			case 1: m_ad_cycles_left = 320; break;
   699→			case 2: m_ad_cycles_left = 640; break;
   700→			case 3: m_ad_cycles_left = 1280; break;
   701→		}
   702→	}
   703→
   704→	m_ad_mode1 = data;
   705→}
