  1031→//-------------------------------------------------
  1032→//  tlcs900_check_hdma - check and process HDMA
  1033→//-------------------------------------------------
  1034→
  1035→void tmp94c241_device::tlcs900_check_hdma()
  1036→{
  1037→	// HDMA can only be performed if interrupts are allowed
  1038→	if ((m_sr.b.h & 0x70) == 0x70)
  1039→		return;  // All interrupts masked
  1040→
  1041→	// Check channels in priority order (0 highest, 3 lowest)
  1042→	for (int channel = 0; channel < 4; channel++)
  1043→	{
  1044→		if (tlcs900_process_hdma(channel))
  1045→			return;  // Only process one transfer per call
  1046→	}
  1047→}
