   914→//-------------------------------------------------
   915→//  tlcs900_process_hdma - process a single HDMA
   916→//  transfer for a channel
   917→//-------------------------------------------------
   918→
   919→int tmp94c241_device::tlcs900_process_hdma(int channel)
   920→{
   921→	// Get DMA start vector for this channel
   922→	uint8_t start_vector = m_dma_vector[channel];
   923→	if (start_vector == 0)
   924→		return 0;  // Channel not configured
   925→
   926→	// Find which interrupt this start vector corresponds to
   927→	int irq = -1;
   928→	for (int i = 0; i < NUM_MASKABLE_IRQS; i++)
   929→	{
   930→		if (tmp94c241_irq_vector_map[i].dma_start_vector == start_vector)
   931→		{
   932→			irq = i;
   933→			break;
   934→		}
   935→	}
   936→
   937→	if (irq < 0)
   938→		return 0;  // No matching interrupt found
   939→
   940→	// Check if the interrupt flag is set (DMA trigger condition)
   941→	if (!(m_int_reg[tmp94c241_irq_vector_map[irq].reg] & tmp94c241_irq_vector_map[irq].iff))
   942→		return 0;  // Interrupt not pending
   943→
   944→	// Decode DMAM mode register
   945→	// TMP94C241 DMAM format:
   946→	// Bits 7-6: Transfer mode (unused in cycle-steal implementation)
   947→	// Bits 5-4: Source addressing (00=fixed, 01=increment, 10=decrement)
   948→	// Bits 3-2: Dest addressing (00=fixed, 01=increment, 10=decrement)
   949→	// Bits 1-0: Data size (00=byte, 01=word, 10=long)
   950→	uint8_t dmam = m_dmam[channel].b.l;
   951→
   952→	// Data size (bits 1-0)
   953→	int data_size;
   954→	switch (dmam & 0x03)
   955→	{
   956→		case 0x00: data_size = 1; break;  // byte
   957→		case 0x01: data_size = 2; break;  // word
   958→		case 0x02: data_size = 4; break;  // long
   959→		default:   data_size = 1; break;  // reserved -> byte
   960→	}
   961→
   962→	// Destination addressing (bits 3-2)
   963→	int dst_dir;
   964→	switch ((dmam >> 2) & 0x03)
   965→	{
   966→		case 0x01: dst_dir = 1; break;   // increment
   967→		case 0x02: dst_dir = -1; break;  // decrement
   968→		default:   dst_dir = 0; break;   // fixed
   969→	}
   970→
   971→	// Source addressing (bits 5-4)
   972→	int src_dir;
   973→	switch ((dmam >> 4) & 0x03)
   974→	{
   975→		case 0x01: src_dir = 1; break;   // increment
   976→		case 0x02: src_dir = -1; break;  // decrement
   977→		default:   src_dir = 0; break;   // fixed
   978→	}
   979→
   980→	// Perform the DMA transfer
   981→	uint32_t src = m_dmas[channel].d;
   982→	uint32_t dst = m_dmad[channel].d;
   983→
   984→	switch (data_size)
   985→	{
   986→		case 1:
   987→			WRMEM(dst, RDMEM(src));
   988→			m_cycles += 8;
   989→			break;
   990→		case 2:
   991→			WRMEMW(dst, RDMEMW(src));
   992→			m_cycles += 8;
   993→			break;
   994→		case 4:
   995→			WRMEML(dst, RDMEML(src));
   996→			m_cycles += 12;
   997→			break;
   998→	}
   999→
  1000→	// Update source and destination addresses
  1001→	m_dmas[channel].d += src_dir * data_size;
  1002→	m_dmad[channel].d += dst_dir * data_size;
  1003→
  1004→	// Decrement transfer count
  1005→	m_dmac[channel].w.l -= 1;
  1006→
  1007→	// Check for transfer completion
  1008→	if (m_dmac[channel].w.l == 0)
  1009→	{
  1010→		// Clear DMA vector to disable channel
  1011→		m_dma_vector[channel] = 0;
  1012→
  1013→		// Set completion interrupt flag
  1014→		switch (channel)
  1015→		{
  1016→			case 0: m_int_reg[INTETC01] |= 0x08; break;
  1017→			case 1: m_int_reg[INTETC01] |= 0x80; break;
  1018→			case 2: m_int_reg[INTETC23] |= 0x08; break;
  1019→			case 3: m_int_reg[INTETC23] |= 0x80; break;
  1020→		}
  1021→		m_check_irqs = 1;
  1022→	}
  1023→
  1024→	// Clear the triggering interrupt flag
  1025→	m_int_reg[tmp94c241_irq_vector_map[irq].reg] &= ~tmp94c241_irq_vector_map[irq].iff;
  1026→
  1027→	return 1;  // Transfer performed
  1028→}
