  1152→//-------------------------------------------------
  1153→//  tlcs900_handle_timers -
  1154→//-------------------------------------------------
  1155→
  1156→// Prescaler shift amounts corresponding to each possible timer input clock source:
  1157→static constexpr uint8_t T1 = 3;
  1158→static constexpr uint8_t T4 = 5;
  1159→static constexpr uint8_t T16 = 7;
  1160→static constexpr uint8_t T256 = 11;
  1161→
  1162→void tmp94c241_device::tlcs900_handle_timers()
  1163→{
  1164→	auto const update_timer_count =
  1165→			[this, old_pre = m_timer_pre] (
  1166→					uint8_t timer_index,
  1167→					uint8_t input_clk_select,
  1168→					uint8_t s1,
  1169→					uint8_t s2,
  1170→					uint8_t s3)
  1171→			{
  1172→				switch (input_clk_select)
  1173→				{
  1174→					case 0:
  1175→					/* Not yet implemented.
  1176→					    - For the 8 bit timers: TIO, TO0TRG, invalid and TO2TRG
  1177→					    - For all 16 bit timers: TIA
  1178→					*/
  1179→					break;
  1180→					case 1: m_timer_change[timer_index] += ((m_timer_pre >> s1) - (old_pre >> s1)); break;
  1181→					case 2: m_timer_change[timer_index] += ((m_timer_pre >> s2) - (old_pre >> s2)); break;
  1182→					case 3: m_timer_change[timer_index] += ((m_timer_pre >> s3) - (old_pre >> s3)); break;
  1183→				}
  1184→			};
  1185→
  1186→	auto const timer_8bits =
  1187→			[this] (
  1188→					uint8_t timer_index,
  1189→					uint8_t timer_reg,
  1190→					uint8_t interrupt,
  1191→					uint8_t interrupt_mask,
  1192→					uint8_t operating_mode,
  1193→					bool invert)
  1194→			{
  1195→				bool match;
  1196→				for ( ; m_timer_change[timer_index] > 0; m_timer_change[timer_index]--)
  1197→				{
  1198→					m_timer_8[timer_index]++;
  1199→					match = m_timer_8[timer_index] == m_treg_8[timer_reg];
  1200→					if (timer_index == 1)
  1201→					{
  1202→						m_serial[0]->TO2_trigger(match);
  1203→						m_serial[1]->TO2_trigger(match);
  1204→					}
  1205→					if (match)
  1206→					{
  1207→						if (BIT(timer_index, 0) == 0)
  1208→						{
  1209→							if (operating_mode == 0) // mode == MODE_8BIT_TIMER
  1210→								m_timer_change[timer_index | 1]++;
  1211→
  1212→							// In 16-bit timer mode the timer should not be reset
  1213→							if (operating_mode != 1) // mode != MODE_16BIT_TIMER
  1214→							{
  1215→								m_timer_8[timer_index] = 0;
  1216→								m_int_reg[interrupt] |= interrupt_mask;
  1217→								m_check_irqs = 1;
  1218→							}
  1219→						}
  1220→						else
  1221→						{
  1222→							m_timer_8[timer_index] = 0;
  1223→							m_int_reg[interrupt] |= interrupt_mask;
  1224→							m_check_irqs = 1;
  1225→
  1226→							// In 16-bit timer mode also reset its 8-bit counterpart (timer N-1)
  1227→							if (operating_mode == 1) // mode == MODE_16BIT_TIMER
  1228→								m_timer_8[timer_index & ~1] = 0;
  1229→						}
  1230→
  1231→						if (invert)
  1232→							change_timer_flipflop(timer_index | 1, FF_INVERT);
  1233→					}
  1234→				}
  1235→			};
  1236→
  1237→	auto const timer_16bits =
  1238→			[this] (
  1239→					uint8_t timer_id,
  1240→					uint8_t timer_reg_low,
  1241→					uint8_t timer_reg_high,
  1242→					uint8_t tffcr,
  1243→					uint8_t interrupt)
  1244→			{
  1245→				/*
  1246→				    timer_id 4  =>  m_timer_16[0]  m_timer_change[4]
  1247→				    timer_id 6  =>  m_timer_16[1]  m_timer_change[5]
  1248→				    timer_id 8  =>  m_timer_16[2]  m_timer_change[6]
  1249→				    timer_id A  =>  m_timer_16[3]  m_timer_change[7]
  1250→				*/
  1251→				uint8_t timer_index = (timer_id - 4)/2;
  1252→
  1253→				for ( ; m_timer_change[timer_index + 4] > 0; m_timer_change[timer_index + 4]--)
  1254→				{
  1255→					m_timer_16[timer_index]++;
  1256→					// TODO: also check for criteria of up counter matching CAPn registers
  1257→					if (((m_timer_16[timer_index] == m_treg_16[timer_reg_high]) && BIT(tffcr, 3)) ||
  1258→							((m_timer_16[timer_index] == m_treg_16[timer_reg_low]) && BIT(tffcr, 2)) )
  1259→					{
  1260→						change_timer_flipflop(timer_id, FF_INVERT);
  1261→						m_timer_16[timer_index] = 0;
  1262→						m_int_reg[interrupt] |= 0x08;
  1263→						m_check_irqs = 1;
  1264→					}
  1265→				}
  1266→			};
  1267→
  1268→	if (BIT(m_t16run, 7)) // prescaler is active
  1269→		m_timer_pre += m_cycles;
  1270→
  1271→	if (BIT(m_t8run, 0)) // Timer 0 is running
  1272→	{
  1273→		update_timer_count(0, m_t01mod & 3, T1, T4, T16);
  1274→		timer_8bits(
  1275→				0, TREG0, INTET01, 0x08,
  1276→				(m_t01mod >> 6) & 3, // TO1_OPERATING_MODE
  1277→				(m_tffcr & 3) == 2); // "FF1 Invert Enable" && "Invert by 8-bit timer 0"
  1278→	}
  1279→
  1280→	if (BIT(m_t8run, 1)) // Timer 1 is running
  1281→	{
  1282→		update_timer_count(1, (m_t01mod >> 2) & 3, T1, T16, T256);
  1283→		timer_8bits(
  1284→				1, TREG1, INTET01, 0x80,
  1285→				(m_t01mod >> 6) & 3, // TO1_OPERATING_MODE
  1286→				(m_tffcr & 3) == 3); // "FF1 Invert Enable" && "Invert by 8-bit timer 1"
  1287→	}
  1288→
  1289→	if (BIT(m_t8run, 2)) // Timer 2 is running
  1290→	{
  1291→		update_timer_count(2, m_t23mod & 3, T1, T4, T16);
  1292→		timer_8bits(
  1293→				2, TREG2, INTET23, 0x08,
  1294→				(m_t23mod >> 6) & 3, // T23_OPERATING_MODE
  1295→				((m_tffcr >> 4) & 3) == 2); // "FF3 Invert Enable" && "Invert by 8-bit timer 2"
  1296→	}
  1297→
  1298→	if (BIT(m_t8run, 3)) // Timer 3 is running
  1299→	{
  1300→		update_timer_count(3, (m_t23mod >> 2) & 3, T1, T16, T256);
  1301→		timer_8bits(
  1302→				3, TREG3, INTET23, 0x80,
  1303→				(m_t23mod >> 6) & 3, // T23_OPERATING_MODE
  1304→				((m_tffcr >> 4) & 3) == 3); // "FF3 Invert Enable" && "Invert by 8-bit timer 3"
  1305→	}
  1306→
  1307→	if (BIT(m_t16run, 0)) // Timer 4 is running
  1308→	{
  1309→		update_timer_count(4, m_t4mod & 3, T1, T4, T16);
  1310→		timer_16bits(4, TREG4, TREG5, m_t4ffcr, INTET45);
  1311→	}
  1312→
  1313→	if (BIT(m_t16run, 1)) // Timer 6 is running
  1314→	{
  1315→		update_timer_count(5, m_t6mod & 3, T1, T4, T16);
  1316→		timer_16bits(6, TREG6, TREG7, m_t6ffcr, INTET67);
  1317→	}
  1318→
  1319→	if (BIT(m_t16run, 2)) // Timer 8 is running
  1320→	{
  1321→		update_timer_count(6, m_t8mod & 3, T1, T4, T16);
  1322→		timer_16bits(8, TREG8, TREG9, m_t8ffcr, INTET89);
  1323→	}
  1324→
  1325→	if (BIT(m_t16run, 3)) // Timer A is running
  1326→	{
  1327→		update_timer_count(7, m_tamod & 3, T1, T4, T16);
  1328→		timer_16bits(0xa, TREGA, TREGB, m_taffcr, INTETAB);
  1329→	}
  1330→
  1331→	m_timer_pre &= 0xffffff;
  1332→}
