   267→{
   268→	do
   269→	{
   270→		const tlcs900inst *inst;
   271→
   272→		m_cycles = 0;
   273→
   274→		if ( m_check_irqs )
   275→		{
   276→			tlcs900_check_irqs();
   277→			m_check_irqs = 0;
   278→		}
   279→
   280→		if ( m_halted )
   281→		{
   282→			debugger_wait_hook();
   283→			m_cycles += 8;
   284→		}
   285→		else
   286→		{
   287→			debugger_instruction_hook( m_pc.d );
   288→
   289→			m_op = RDOP();
   290→			inst = &m_mnemonic[m_op];
   291→			prepare_operands( inst );
   292→
   293→			/* Execute the instruction */
   294→			(this->*inst->opfunc)();
   295→			m_cycles += inst->cycles;
   296→		}
   297→
   298→		tlcs900_handle_ad();
   299→
   300→		tlcs900_handle_timers();
   301→
   302→		tlcs900_check_hdma();
   303→
   304→		m_icount -= m_cycles;
   305→	} while ( m_icount > 0 );
   306→}
