   406→
   407→void tmp94c241_device::change_timer_flipflop(uint8_t flipflop, uint8_t operation)
   408→{
   409→	/* First we update the timer flip-flop */
   410→	bool &ff_state = m_timer_flipflops[flipflop];
   411→
   412→	switch (operation)
   413→	{
   414→		case FF_INVERT:
   415→			ff_state = !ff_state;
   416→			break;
   417→		case FF_SET:
   418→			ff_state = true;
   419→			break;
   420→		case FF_CLEAR:
   421→			ff_state = false;
   422→			break;
   423→		default:
   424→			// invalid operation
   425→			return;
   426→	}
   427→
   428→	/* The value of the flipflop is only exposed to a pin in certain modes of operation
   429→	   determined by fields of the port function registers.
   430→
   431→	   So here we bail out if the flipflop is not routed to its corresponding port bit:
   432→	*/
   433→	switch (flipflop)
   434→	{
   435→		case 0x1:
   436→			if (!BIT(m_port_function[PORT_C], 0) || BIT(m_port_control[PORT_C], 0)) return;
   437→			break;
   438→		case 0x7:
   439→			if (!BIT(m_port_function[PORT_C], 0) || !BIT(m_port_control[PORT_C], 0)) return;
   440→			break;
   441→		case 0x3:
   442→			if (!BIT(m_port_function[PORT_C], 1) || BIT(m_port_control[PORT_C], 1)) return;
   443→			break;
   444→		case 0xb:
   445→			if (!BIT(m_port_function[PORT_C], 1) || !BIT(m_port_control[PORT_C], 1)) return;
   446→			break;
   447→		case 0x4:
   448→			if (!BIT(m_port_function[PORT_D], 0)) return;
   449→			break;
   450→		case 0x6:
   451→			if (!BIT(m_port_function[PORT_D], 4)) return;
   452→			break;
   453→		case 0x8:
   454→			if (!BIT(m_port_function[PORT_E], 0)) return;
   455→			break;
   456→		case 0xA:
   457→			if (!BIT(m_port_function[PORT_E], 4)) return;
   458→			break;
   459→		default:
   460→			// invalid flip flop
   461→			return;
   462→	}
   463→
   464→	// And here we actually send the value to the corresponding pin
   465→	uint8_t new_port_value = 0;
   466→	switch (flipflop)
   467→	{
   468→		case 0x1:
   469→		case 0x7:
   470→			new_port_value = m_port_latch[PORT_C] & 0xfe;
   471→			if (ff_state) new_port_value |= 0x01;
   472→			port_w<PORT_C>(new_port_value);
   473→			break;
   474→		case 0x3:
   475→		case 0xb:
   476→			new_port_value = m_port_latch[PORT_C] & 0xfd;
   477→			if (ff_state) new_port_value |= 0x02;
   478→			port_w<PORT_C>(new_port_value);
   479→			break;
   480→		case 0x4:
   481→			new_port_value = m_port_latch[PORT_D] & 0xfe;
   482→			if (ff_state) new_port_value |= 0x01;
   483→			port_w<PORT_D>(new_port_value);
   484→			break;
   485→		case 0x6:
   486→			new_port_value = m_port_latch[PORT_D] & 0xef;
   487→			if (ff_state) new_port_value |= 0x10;
   488→			port_w<PORT_D>(new_port_value);
   489→			break;
   490→		case 0x8:
   491→			new_port_value = m_port_latch[PORT_E] & 0xfe;
   492→			if (ff_state) new_port_value |= 0x01;
   493→			port_w<PORT_E>(new_port_value);
   494→			break;
   495→		case 0xa:
   496→			new_port_value = m_port_latch[PORT_E] & 0xef;
   497→			if (ff_state) new_port_value |= 0x10;
   498→			port_w<PORT_E>(new_port_value);
   499→			break;
   500→	}
   501→}
