  1050→//-------------------------------------------------
  1051→//  tlcs900_check_irqs -
  1052→//-------------------------------------------------
  1053→
  1054→void tmp94c241_device::tlcs900_check_irqs()
  1055→{
  1056→	// Check for NMI
  1057→	if (m_nmi_state == ASSERT_LINE)
  1058→	{
  1059→		m_xssp.d -= 4;
  1060→		WRMEML(m_xssp.d, m_pc.d);
  1061→		m_xssp.d -= 2;
  1062→		WRMEMW(m_xssp.d, m_sr.w.l);
  1063→		m_pc.d = RDMEML( 0xffff00 + 0x20 );
  1064→		m_cycles += 18;
  1065→		m_prefetch_clear = true;
  1066→		m_halted = 0;
  1067→		m_nmi_state = CLEAR_LINE;
  1068→		return;
  1069→	}
  1070→
  1071→	/* Check regular IRQs
  1072→	   The smaller the vector value, the higher the priority. */
  1073→	int irq_vectors[8] = { -1, -1, -1, -1, -1, -1, -1, -1 };
  1074→	for (int i = NUM_MASKABLE_IRQS - 1; i >= 0; i--)
  1075→	{
  1076→		if (m_int_reg[tmp94c241_irq_vector_map[i].reg] & tmp94c241_irq_vector_map[i].iff)
  1077→		{
  1078→			switch (tmp94c241_irq_vector_map[i].iff)
  1079→			{
  1080→				case 0x80:
  1081→					irq_vectors[(m_int_reg[tmp94c241_irq_vector_map[i].reg] >> 4) & 0x07] = i;
  1082→					break;
  1083→				case 0x08:
  1084→					irq_vectors[m_int_reg[tmp94c241_irq_vector_map[i].reg] & 0x07] = i;
  1085→					break;
  1086→			}
  1087→		}
  1088→	}
  1089→
  1090→	// Check highest allowed priority IRQ
  1091→	int irq = -1;
  1092→	int level = 0;
  1093→	for (int i = std::max(1, (m_sr.b.h & 0x70) >> 4); i < 7; i++)
  1094→	{
  1095→		if (irq_vectors[i] >= 0)
  1096→		{
  1097→			irq = irq_vectors[i];
  1098→			level = i + 1;
  1099→		}
  1100→	}
  1101→
  1102→	// Take IRQ
  1103→	if (irq >= 0)
  1104→	{
  1105→		uint8_t vector = tmp94c241_irq_vector_map[irq].vector;
  1106→
  1107→		m_xssp.d -= 4;
  1108→		WRMEML(m_xssp.d, m_pc.d);
  1109→		m_xssp.d -= 2;
  1110→		WRMEMW(m_xssp.d, m_sr.w.l);
  1111→
  1112→		// Mask off any lower priority interrupts
  1113→		m_sr.b.h = (m_sr.b.h & 0x8f) | (level << 4);
  1114→
  1115→		m_pc.d = RDMEML(0xffff00 + vector);
  1116→
  1117→		m_cycles += 18;
  1118→		m_prefetch_clear = true;
  1119→
  1120→		m_halted = 0;
  1121→
  1122→		// Clear taken IRQ
  1123→		m_int_reg[tmp94c241_irq_vector_map[irq].reg] &= ~ tmp94c241_irq_vector_map[irq].iff;
  1124→
  1125→		// notify the debugger
  1126→		if (machine().debug_enabled())
  1127→		{
  1128→			int8_t default_priority = vector/4 + 1;
  1129→			if (vector > 0x3c)
  1130→				default_priority--; // skip reserved one
  1131→
  1132→			// For now we can't pass a string with the interrupt name
  1133→			// so, here we'll get a message that says things like "IRQ 20"
  1134→			// and we can look up the TMP94C241 datasheet and find under
  1135→			// "Default priority" on the interrupt table that
  1136→			// "20" means "INTT0: 8-bit timer (Timer 0)"
  1137→			debug()->interrupt_hook(default_priority, m_pc.d);
  1138→		}
  1139→	}
  1140→}
