  1336→//  execute_set_input - called when a synchronized
  1337→//  input is changed
  1338→//-------------------------------------------------
  1339→
  1340→void tmp94c241_device::execute_set_input(int input, int level)
  1341→{
  1342→	auto const update_int_reg =
  1343→			[this, level, input] (uint8_t reg, uint8_t mask)
  1344→			{
  1345→				if (level != m_level[input])
  1346→				{
  1347→					m_level[input] = level;
  1348→					if (level == ASSERT_LINE)
  1349→						m_int_reg[reg] |= mask;
  1350→					else
  1351→						m_int_reg[reg] &= ~mask;
  1352→				}
  1353→			};
  1354→
  1355→	switch (input)
  1356→	{
  1357→		case INPUT_LINE_NMI:
  1358→		case TLCS900_NMI:
  1359→			if (level != m_level[TLCS900_NMI])
  1360→			{
  1361→				m_level[TLCS900_NMI] = level;
  1362→				if (level == ASSERT_LINE)
  1363→					m_nmi_state = ASSERT_LINE;
  1364→			}
  1365→			break;
  1366→
  1367→		case TLCS900_INTWD:
  1368→			break;
  1369→
  1370→		case TLCS900_INT0:
  1371→			if (m_iimc & 0x02)
  1372→			{
  1373→				// Rising edge detect
  1374→				if (level != m_level[TLCS900_INT0] && level == ASSERT_LINE)
  1375→				{
  1376→					// Leave HALT state
  1377→					m_halted = 0;
  1378→					m_int_reg[INTE0AD] |= 0x08;
  1379→				}
  1380→				m_level[TLCS900_INT0] = level;
  1381→			}
  1382→			else
  1383→			{
  1384→				// Level detect
  1385→				update_int_reg(INTE0AD, 0x08);
  1386→			}
  1387→			break;
  1388→
  1389→		case TLCS900_INT4: update_int_reg(INTE45, 0x08); break;
  1390→		case TLCS900_INT5: update_int_reg(INTE45, 0x80); break;
  1391→		case TLCS900_INT6: update_int_reg(INTE67, 0x08); break;
  1392→		case TLCS900_INT7: update_int_reg(INTE67, 0x80); break;
  1393→		case TLCS900_INT8: update_int_reg(INTE89, 0x08); break;
  1394→		case TLCS900_INT9: update_int_reg(INTE89, 0x80); break;
  1395→		case TLCS900_INTA: update_int_reg(INTEAB, 0x08); break;
  1396→		case TLCS900_INTB: update_int_reg(INTEAB, 0x80); break;
  1397→
  1398→		default:
  1399→			// invalid
  1400→			return;
  1401→	}
  1402→	m_check_irqs = 1;
  1403→}
