    81→inline uint8_t tlcs900_device::RDOP()
    82→{
    83→	uint8_t data;
    84→
    85→	if ( m_prefetch_clear )
    86→	{
    87→		for ( int i = 0; i < 4; i++ )
    88→		{
    89→			m_prefetch[ i ] = RDMEM( m_pc.d + i );
    90→		}
    91→		m_prefetch_index = 0;
    92→		m_prefetch_clear = false;
    93→	}
    94→	else
    95→	{
    96→		m_prefetch[ m_prefetch_index ] = RDMEM( m_pc.d + 3 );
    97→		m_prefetch_index = ( m_prefetch_index + 1 ) & 0x03;
